$_MODULE['<{vatnumber}prestashop>vatnumber_d17a37903c2ff7ec71c5bae45d1e5a22'] = 'Data nel formato AAAA-MM-GG, oppure vuoto per verificare tutto. I numeri in coda di clienti senza modifiche all\'indirizzo e senza ordini da questa data vengono rimossi dalla coda di verifica. Utile dopo l\'aggiornamento di un negozio con anni di vecchi indirizzi. I numeri rimossi vengono semplicemente ricontrollati dal vivo se il cliente dovesse tornare.';
$_MODULE['<{vatnumber}prestashop>vatnumber_b9f5c797ebbf55adccdd8539a65a0241'] = 'Disattivato';
$_MODULE['<{vatnumber}prestashop>vatnumber_ac2f6a9cfa32070c4499f4879221058e'] = 'Disattivato (predefinito): i clienti ottengono subito l\'esenzione IVA, anche mentre il loro numero e ancora in attesa di verifica. Attivato: i clienti continuano a pagare l\'IVA finche VIES non ha confermato il numero. Attivato e piu sicuro per voi, disattivato e piu comodo per il cliente. Rilevante solo quando la verifica automatica e attiva. I numeri respinti da VIES non ottengono mai l\'esenzione, in nessuna delle due modalita.';
$_MODULE['<{vatnumber}prestashop>vatnumber_c3611ab7e05da6ec6a6d66098df71627'] = 'Ogni esecuzione verifica %d numeri. Per smaltire piu in fretta una coda grande, aggiungete &limit=%d all\'URL (il massimo per esecuzione).';
$_MODULE['<{vatnumber}prestashop>vatnumber_00d23a76e43b46dae9ec7aa9dcbebb32'] = 'Attivato';
$_MODULE['<{vatnumber}prestashop>vatnumber_8aa92523f0a021be484f930bc2c1d452'] = 'L\'attivazione aggiunge una semplice casella per le esenzioni IVA. Usatela per esenzioni IVA non legate a una partita IVA. Una casella spuntata si riconosce da \'%s\' nel back office, nel campo della partita IVA in Clienti -> Indirizzi.';
$_MODULE['<{vatnumber}prestashop>vatnumber_b25c4046a0e5c918765d51e10d709113'] = 'Inserite il numero completo incluso il prefisso paese di due lettere, per esempio %s. Spazi, punti e trattini non sono un problema. Usate EL o GR per la Grecia e XI per l\'Irlanda del Nord.';
$_MODULE['<{vatnumber}prestashop>vatnumber_2b094aac9f12f2abd921781ec657b254'] = 'Esenta solo dopo una verifica riuscita';
